package com.cyberyichen.bloub;
import android.content.Context;import android.hardware.camera2.*;import android.media.*;import android.util.*;import org.json.*;import java.util.*;import java.io.*;
final class VideoEncoding {
 private static final Map<String,JSONObject> cache=new HashMap<>();
 static synchronized JSONObject capabilities(Context context,String camera)throws Exception{JSONObject known=cache.get(camera);if(known!=null)return new JSONObject(known.toString());CameraCharacteristics c=((CameraManager)context.getSystemService(Context.CAMERA_SERVICE)).getCameraCharacteristics(camera);Size[] sizes=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP).getOutputSizes(MediaRecorder.class);JSONArray codecs=new JSONArray();for(String id:new String[]{"h264","h265"}){String mime=id.equals("h264")?"video/avc":"video/hevc";JSONArray formats=new JSONArray();int min=20000,max=128;ArrayList<Size> ordered=new ArrayList<>();if(sizes!=null)Collections.addAll(ordered,sizes);ordered.sort((a,z)->Integer.compare(z.getWidth()*z.getHeight(),a.getWidth()*a.getHeight()));HashSet<String> used=new HashSet<>();for(Size size:ordered){int w=camera.equals("2")?size.getHeight():size.getWidth(),h=camera.equals("2")?size.getWidth():size.getHeight();if(w*h>2073600||Math.min(w,h)<240)continue;String value=w+"x"+h;if(!used.add(value))continue;JSONArray fps=new JSONArray();int low=20000,high=128;for(MediaCodecInfo info:new MediaCodecList(MediaCodecList.REGULAR_CODECS).getCodecInfos()){if(!info.isEncoder())continue;try{MediaCodecInfo.CodecCapabilities cap=info.getCapabilitiesForType(mime);boolean surface=false;for(int color:cap.colorFormats)if(color==MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface)surface=true;if(!surface)continue;MediaCodecInfo.VideoCapabilities v=cap.getVideoCapabilities();if(!v.isSizeSupported(w,h)||!v.isSizeSupported(h,w))continue;low=Math.min(low,Math.max(128,(v.getBitrateRange().getLower()+999)/1000));high=Math.max(high,Math.min(20000,v.getBitrateRange().getUpper()/1000));for(int f:new int[]{10,15,24,25,30})if(v.areSizeAndRateSupported(w,h,f)&&v.areSizeAndRateSupported(h,w,f)){boolean present=false;for(int j=0;j<fps.length();j++)if(fps.optInt(j)==f)present=true;if(!present)fps.put(f);}}catch(IllegalArgumentException ignored){}}
 if(fps.length()>0){min=Math.min(min,low);max=Math.max(max,high);formats.put(new JSONObject().put("value",value).put("width",w).put("height",h).put("frameRates",fps).put("minBitrateKbps",low).put("maxBitrateKbps",high));}}
 if(formats.length()>0){String automatic=formats.getJSONObject(0).getString("value");double best=Double.MAX_VALUE;for(int j=0;j<formats.length();j++){JSONObject f=formats.getJSONObject(j);int w=f.getInt("width"),h=f.getInt("height");double score=Math.abs(w/(double)h-4d/3)*10000000+Math.abs(w*h-1228800);if(score<best){best=score;automatic=f.getString("value");}}codecs.put(new JSONObject().put("id",id).put("label",id.equals("h264")?"H.264":"H.265").put("automaticResolution",automatic).put("formats",formats).put("minBitrateKbps",min).put("maxBitrateKbps",max));}}
 JSONObject result=new JSONObject().put("codecs",codecs);cache.put(camera,result);return new JSONObject(result.toString());}
 static JSONObject format(Context context,String camera,JSONObject config)throws Exception{EncodingSpec.validate(config);JSONArray codecs=capabilities(context,camera).getJSONArray("codecs");for(int i=0;i<codecs.length();i++){JSONObject codec=codecs.getJSONObject(i);if(!codec.getString("id").equals(config.getString("videoCodec")))continue;String resolution=config.getString("resolution");if(resolution.equals("auto"))resolution=codec.getString("automaticResolution");JSONArray formats=codec.getJSONArray("formats");for(int j=0;j<formats.length();j++){JSONObject f=formats.getJSONObject(j);if(!resolution.equals(f.getString("value")))continue;boolean valid=false;JSONArray rates=f.getJSONArray("frameRates");for(int k=0;k<rates.length();k++)if(rates.getInt(k)==config.getInt("frameRate"))valid=true;if(!valid)throw new IOException("设备不支持所选帧率");int rate=config.getInt("bitrateKbps");if(rate<f.getInt("minBitrateKbps")||rate>f.getInt("maxBitrateKbps"))throw new IOException("码率超出设备支持范围");return f;}}
 throw new IOException("设备不支持所选编码或分辨率");}
 static Size size(Context context,String camera,JSONObject config)throws Exception{JSONObject f=format(context,camera,config);return camera.equals("2")?new Size(f.getInt("height"),f.getInt("width")):new Size(f.getInt("width"),f.getInt("height"));}
}
